    for (i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
    }

    printf("Enter element to search: ");
    scanf("%d", &key);

    pos = binarySearch(a, 0, n - 1, key);

    if (pos != -1)
    {
        printf("Success: %d found at index %d (position %d).\n", key, pos, pos + 1);
    }
    else
    {
        printf("Element %d not found in the array.\n", key);
    }

    return 0;
}

