#include <stdio.h>

void findMinMax(int a[], int low, int high, int *min, int *max)
{
    int mid;
    int leftMin, leftMax, rightMin, rightMax;

    if (low == high)
    {
        *min = a[low];
        *max = a[low];
        return;
    }

    if (high == low + 1)
    {
        if (a[low] < a[high])
        {
            *min = a[low];
            *max = a[high];
        }
        else
        {
            *min = a[high];
            *max = a[low];
        }
        return;
    }

    mid = (low + high) / 2;

    findMinMax(a, low, mid, &leftMin, &leftMax);
    findMinMax(a, mid + 1, high, &rightMin, &rightMax);

    if (leftMin < rightMin)
    {
        *min = leftMin;
    }
    else
    {
        *min = rightMin;
    }

    if (leftMax > rightMax)
    {
        *max = leftMax;
    }
    else
    {
        *max = rightMax;
    }
}

int main()
{
    int n, i, min, max;
    int a[50];

    printf("Enter number of elements: ");
    scanf("%d", &n);

    printf("Enter %d elements: ", n);
    for (i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
    }

    findMinMax(a, 0, n - 1, &min, &max);

    printf("Minimum element = %d\n", min);
    printf("Maximum element = %d\n", max);

    return 0;
}

