void decimalToBinary(int n)
{
    int bits[32], idx = 0, i;

    if (n == 0)
    {
        printf("0\n");
        return;
    }

    while (n > 0)
    {
        bits[idx] = n % 2;
        idx++;
        n /= 2;
    }

    for (i = idx - 1; i >= 0; i--)
    {
        printf("%d", bits[i]);
    }

    printf("\n");
}

void hexToBinary(char hex[])
{
    int i, b, val;
    char c;

    for (i = 0; hex[i] != '\0'; i++)
    {
        c = toupper(hex[i]);
        val = (c >= '0' && c <= '9') ? (c - '0') : (c - 'A' + 10);

        for (b = 3; b >= 0; b--)
        {
            printf("%d", (val >> b) & 1);
        }
    }

    printf("\n");
}

int main()
{
    int dec;
    char hex[20];

    printf("Enter a Decimal number: ");
    scanf("%d", &dec);

    printf("Binary of Decimal %d = ", dec);
    decimalToBinary(dec);

    printf("\nEnter a Hexadecimal number: ");
    scanf("%s", hex);

    printf("Binary of Hexadecimal %s = ", hex);
    hexToBinary(hex);

    return 0;
}

